const base=process.env.MOBILE_REVIEW_BASE??'http://localhost:4182';
import {chromium} from '@playwright/test';
const b=await chromium.launch({executablePath:'/usr/bin/chromium',args:['--no-sandbox']});const p=await b.newPage({viewport:{width:390,height:844}});await p.addInitScript(()=>localStorage.setItem('game100garage:analytics-consent:v1','denied'));await p.clock.install();await p.goto(`${base}/game022.html`);await p.locator('#challenge-button').click();await p.clock.fastForward(60000);await p.locator('#pause-button').click();const paused=await p.evaluate(()=>window.__game022.snapshot.elapsed_ms);await p.clock.fastForward(240000);if(await p.evaluate(()=>window.__game022.state)!=='paused')throw Error('pause advanced');await p.locator('#resume-button').click();await p.clock.fastForward(121000);await p.waitForFunction(()=>window.__game022.state==='result');const value=await p.evaluate(()=>({state:window.__game022.state,best:localStorage.getItem('web-mini-arcade:v1:game022:challenge-best-v1'),stats:window.__game022.stats,saved:localStorage.getItem('web-mini-arcade:v1:game022:session')}));if(value.best!=='0'||value.stats.clears!==0||value.saved!==null)throw Error(JSON.stringify(value));console.log(JSON.stringify({paused,value}));await b.close();
